<?php
/* Small, database-backed modules required by the ERP specification. */
function ensure_compliance_schema(): void {
    $c=db();
    $sql=[
        "CREATE TABLE IF NOT EXISTS product_categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,image VARCHAR(255) DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
        "CREATE TABLE IF NOT EXISTS shipping_methods (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,cost DECIMAL(12,2) NOT NULL DEFAULT 0,eta VARCHAR(100) NOT NULL DEFAULT '',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
        "CREATE TABLE IF NOT EXISTS contact_messages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL,phone VARCHAR(30) DEFAULT NULL,message TEXT NOT NULL,status ENUM('new','read','resolved') NOT NULL DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
        "CREATE TABLE IF NOT EXISTS testimonials (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED DEFAULT NULL,name VARCHAR(100) NOT NULL,content TEXT NOT NULL,rating TINYINT UNSIGNED NOT NULL DEFAULT 5,is_visible TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
        "CREATE TABLE IF NOT EXISTS return_requests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,reason TEXT NOT NULL,request_type ENUM('return','exchange') NOT NULL DEFAULT 'return',status ENUM('requested','reviewed','approved','rejected','completed') NOT NULL DEFAULT 'requested',admin_notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_return_order(order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
        "CREATE TABLE IF NOT EXISTS website_settings (setting_key VARCHAR(80) PRIMARY KEY,setting_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
        "CREATE TABLE IF NOT EXISTS page_visits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,page_name VARCHAR(60) NOT NULL,visited_on DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_visit_day(visited_on),KEY idx_visit_page(page_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
    ]; foreach($sql as $q)$c->query($q);
    $cols=[];$r=$c->query('SHOW COLUMNS FROM shipping_methods');while($r&&$x=$r->fetch_assoc())$cols[]=$x['Field'];
    if(!in_array('eta',$cols,true))$c->query("ALTER TABLE shipping_methods ADD COLUMN eta VARCHAR(100) NOT NULL DEFAULT '' AFTER cost");
    if(!in_array('is_active',$cols,true))$c->query('ALTER TABLE shipping_methods ADD COLUMN is_active TINYINT(1) NOT NULL DEFAULT 1 AFTER eta');
    if(!in_array('created_at',$cols,true))$c->query('ALTER TABLE shipping_methods ADD COLUMN created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP');
    $c->query("UPDATE shipping_methods SET eta='2–4 hari' WHERE name LIKE 'Reguler%' AND eta=''");
    $c->query("UPDATE shipping_methods SET eta='1 hari' WHERE name LIKE 'Next Day%' AND eta=''");
    $c->query("UPDATE shipping_methods SET eta='Hari ini' WHERE name LIKE 'Same Day%' AND eta=''");
    $defaults=['store_name'=>'ARÔME HOUSE','contact_email'=>'hello@aromehouse.test','contact_phone'=>'+62 812-3456-7890','contact_address'=>'Jakarta, Indonesia','vision'=>'Menjadi rumah parfum pilihan yang membantu setiap orang mengekspresikan karakter dirinya.','mission'=>'Menyediakan pilihan parfum berkualitas, pelayanan yang hangat, dan pengalaman belanja yang mudah serta terpercaya.'];
    $st=$c->prepare('INSERT IGNORE INTO website_settings(setting_key,setting_value) VALUES(?,?)');foreach($defaults as $k=>$v){$st->bind_param('ss',$k,$v);$st->execute();}$st->close();
    $count=$c->query('SELECT COUNT(*) n FROM shipping_methods')->fetch_assoc()['n']??0;if(!$count){$seed=[['Dalam kota (1-2 hari)',10000,'1-2 hari'],['Jabodetabek (2-4 hari)',18000,'2-4 hari'],['Luar kota (3-7 hari)',35000,'3-7 hari']];$st=$c->prepare('INSERT INTO shipping_methods(name,cost,eta) VALUES(?,?,?)');foreach($seed as [$n,$cost,$eta]){$st->bind_param('sds',$n,$cost,$eta);$st->execute();}$st->close();}
}
function site_settings(): array {$rows=[];$r=db()->query('SELECT setting_key,setting_value FROM website_settings');while($r&&$x=$r->fetch_assoc())$rows[$x['setting_key']]=$x['setting_value'];return $rows;}
function active_shipping_methods(): array {$out=[];$r=db()->query('SELECT name,cost FROM shipping_methods WHERE is_active=1 ORDER BY cost,id');while($r&&$x=$r->fetch_assoc())$out[$x['name']]=(int)$x['cost'];return $out;}
function compliance_csrf(): string{return $_SESSION['compliance_csrf']??=bin2hex(random_bytes(32));}
function compliance_ok(): bool{return is_string($_POST['csrf']??null)&&hash_equals(compliance_csrf(),$_POST['csrf']);}
function handle_compliance_action(string $action): never {
    $c=db();try {
        if(!compliance_ok())throw new InvalidArgumentException('Sesi formulir tidak valid. Muat ulang halaman.');
        if($action==='contact_send'){$n=trim($_POST['name']??'');$e=trim($_POST['email']??'');$p=trim($_POST['phone']??'');$m=trim($_POST['message']??'');if($n===''||!filter_var($e,FILTER_VALIDATE_EMAIL)||$m==='')throw new InvalidArgumentException('Nama, email valid, dan pesan wajib diisi.');$st=$c->prepare('INSERT INTO contact_messages(name,email,phone,message) VALUES(?,?,?,?)');$st->bind_param('ssss',$n,$e,$p,$m);$st->execute();$st->close();flash('success','Pesan telah terkirim. Tim kami akan menghubungi Anda.');redirect('?page=contact');}
        if($action==='testimonial_send'){require_login();$m=trim($_POST['content']??'');$rating=(int)($_POST['rating']??5);if($m===''||$rating<1||$rating>5)throw new InvalidArgumentException('Isi testimoni dan rating 1–5.');$id=(int)$_SESSION['user']['id'];$name=$_SESSION['user']['name'];$st=$c->prepare('INSERT INTO testimonials(user_id,name,content,rating,is_visible) VALUES(?,?,?,?,0)');$st->bind_param('issi',$id,$name,$m,$rating);$st->execute();$st->close();flash('success','Terima kasih. Testimoni akan tampil setelah ditinjau admin.');redirect('?page=testimonials');}
        if($action==='return_request'){require_login();$oid=(int)($_POST['order_id']??0);$reason=trim($_POST['reason']??'');$type=$_POST['request_type']??'return';$uid=(int)$_SESSION['user']['id'];if(!$oid||$reason===''||!in_array($type,['return','exchange'],true))throw new InvalidArgumentException('Data retur tidak lengkap.');$st=$c->prepare("SELECT id FROM orders WHERE id=? AND user_id=? AND status IN ('Dikirim','Selesai')");$st->bind_param('ii',$oid,$uid);$st->execute();$valid=$st->get_result()->fetch_assoc();$st->close();if(!$valid)throw new InvalidArgumentException('Pesanan tidak memenuhi syarat pengajuan retur.');$st=$c->prepare('INSERT INTO return_requests(order_id,user_id,reason,request_type) VALUES(?,?,?,?)');$st->bind_param('iiss',$oid,$uid,$reason,$type);$st->execute();$st->close();flash('success','Pengajuan berhasil dikirim dan akan ditinjau admin.');redirect('?page=orders');}
        require_admin();
        if($action==='admin_user_create'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';$role=$_POST['role']??'user';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||!in_array($role,['user','admin','owner'],true))throw new InvalidArgumentException('Lengkapi nama, email, password minimal 8 karakter, dan peran.');$hash=password_hash($password,PASSWORD_DEFAULT);$st=$c->prepare('INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)');$st->bind_param('ssss',$name,$email,$hash,$role);$st->execute();$st->close();flash('success','Pengguna berhasil ditambahkan.');redirect('?page=admin&tab=users');}
        if($action==='admin_category_save'||$action==='admin_shipping_save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if($name==='')throw new InvalidArgumentException('Nama wajib diisi.');if($action==='admin_category_save'){$image=trim($_POST['image']??'');$st=$id?$c->prepare('UPDATE product_categories SET name=?,image=? WHERE id=?'):$c->prepare('INSERT INTO product_categories(name,image) VALUES(?,?)');$id?$st->bind_param('ssi',$name,$image,$id):$st->bind_param('ss',$name,$image);}else{$cost=max(0,(float)($_POST['cost']??0));$eta=trim($_POST['eta']??'');$active=isset($_POST['is_active'])?1:0;$st=$id?$c->prepare('UPDATE shipping_methods SET name=?,cost=?,eta=?,is_active=? WHERE id=?'):$c->prepare('INSERT INTO shipping_methods(name,cost,eta,is_active) VALUES(?,?,?,?)');$id?$st->bind_param('sdsii',$name,$cost,$eta,$active,$id):$st->bind_param('sdsi',$name,$cost,$eta,$active);}$st->execute();$st->close();flash('success','Data berhasil disimpan.');redirect('?page=admin&tab='.($action==='admin_category_save'?'categories':'shipping'));}
        if($action==='admin_category_delete'||$action==='admin_shipping_delete'){$id=(int)($_POST['id']??0);$table=$action==='admin_category_delete'?'product_categories':'shipping_methods';$st=$c->prepare("DELETE FROM $table WHERE id=?");$st->bind_param('i',$id);$st->execute();$st->close();flash('success','Data berhasil dihapus.');redirect('?page=admin&tab='.($table==='product_categories'?'categories':'shipping'));}
        if($action==='admin_testimonial_visibility'){$id=(int)$_POST['id'];$visible=isset($_POST['visible'])?1:0;$st=$c->prepare('UPDATE testimonials SET is_visible=? WHERE id=?');$st->bind_param('ii',$visible,$id);$st->execute();$st->close();redirect('?page=admin&tab=testimonials');}
        if($action==='admin_return_status'){$id=(int)$_POST['id'];$status=$_POST['status']??'';$notes=trim($_POST['admin_notes']??'');if(!in_array($status,['requested','reviewed','approved','rejected','completed'],true))throw new InvalidArgumentException('Status retur tidak valid.');$st=$c->prepare('UPDATE return_requests SET status=?,admin_notes=? WHERE id=?');$st->bind_param('ssi',$status,$notes,$id);$st->execute();$st->close();redirect('?page=admin&tab=returns');}
        if($action==='admin_settings_save'){$allowed=['store_name','contact_email','contact_phone','contact_address','vision','mission'];$st=$c->prepare('INSERT INTO website_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($allowed as $key){$value=trim($_POST[$key]??'');$st->bind_param('ss',$key,$value);$st->execute();}$st->close();flash('success','Pengaturan website disimpan.');redirect('?page=admin&tab=website');}
    } catch(Throwable $e){flash('error',$e instanceof InvalidArgumentException?$e->getMessage():'Aksi gagal diproses.');redirect('?page='.($action==='contact_send'?'contact':'admin'));}
    redirect('?page=admin');
}
?>
